#pragma once
// newton/forces/drives.hpp — external time-dependent and constant forces
// (Taylor §5.5).
//
// Physics: a "drive" is an external force imposed on the system rather than
// generated by it — the hand pushing a swing, an applied E-field, a rocket's
// thrust before it's modeled as mass loss. Taylor introduces the sinusoidal
// drive to study forced/resonant oscillation (§5.5-5.6); combined with
// forces::Spring and forces::LinearDrag via forces::sum(...) it reproduces
// the driven damped oscillator.

#include <cmath>

#include <newton/core/vec3.hpp>

namespace newton::forces {

/// Sinusoidal driving force (Taylor §5.5): F(t) = F0 cos(omega t + phase) dir,
/// with `dir` a unit vector giving the drive's direction (default +x).
///
/// Physics: position- and velocity-independent — purely a function of time.
/// Because it depends explicitly on t it is NOT conservative in Taylor's sense
/// (§4.2 condition (i) asks for position-only forces). At each instant it is
/// uniform, so U(r, t) = -F(t).r works (§4.5), but that U depends on t: the
/// energy T + U is not constant, dE/dt = dU/dt, and the work the drive does is
/// W = integral of F(t).v dt (see analysis::energy_balance).
/// Pair with Spring + LinearDrag to get Taylor's x'' + 2*beta*x' + omega0^2*x
/// = f0 cos(omega t) (see analytic/oscillator.hpp::DrivenOscillator for the
/// closed-form steady-state response).
///
/// C++ note: `dir` is stored as given, not renormalized — the caller is
/// trusted to pass a unit vector (as documented) so the constructor stays a
/// trivial aggregate; scaling by a non-unit `dir` just rescales F0.
struct SinusoidalDrive {
    double F0{1.0};      // amplitude [N]
    double omega{1.0};   // angular frequency [rad/s]
    double phase{0.0};   // phase offset [rad]
    Vec3   dir{1.0, 0.0, 0.0};  // unit direction of the drive

    [[nodiscard]] Vec3 operator()(double t, const Vec3& /*r*/, const Vec3& /*v*/) const {
        return (F0 * std::cos(omega * t + phase)) * dir;
    }
};

/// Constant force, independent of t, r, and v — e.g. constant rocket thrust
/// before switching to a variable-mass model, or the force q E on a charge
/// in a uniform static electric field with no magnetic field.
struct ConstantForce {
    Vec3 F{};  // [N]

    [[nodiscard]] Vec3 operator()(double /*t*/, const Vec3& /*r*/, const Vec3& /*v*/) const {
        return F;
    }
};

}  // namespace newton::forces
